}", "middlewares/unfinished_step.py": """"Before the agent finishes: when its final message says a step is not done, send it back to that step."""


def check(ctx, event):
    final = str(event.get('final_message', ''))
    if 'Not done:' not in final:
        return {'action': 'continue'}
    step = final.split('Not done:', 1)[1].strip()
    return {'action': 'block', 'message': 'You said this is not done: ' + step + ' Do it before you finish.'}
